fn read_identifier(&mut self, first: char) -> Token {
    let mut ident = String::from(first);
    while let Some(&ch) = self.peek() {
        if ch.is_alphanumeric() || ch == '_' {
            ident.push(ch);
            self.advance();
        } else {
            break;
        }
    }

    match ident.as_str() {
        "let" => Token::Let,
        "fn" => Token::Fn,
        "if" => Token::If,
        "else" => Token::Else,
        "return" => Token::Return,
        "while" => Token::While,
        "true" => Token::Boolean(true),
        "false" => Token::Boolean(false),
        "null" => Token::Null,
        _ => Token::Ident(ident),
    }
}

